# api/views.py - Django REST Framework JWT Authentication Service
import hashlib
import hmac
import json
import time
import base64
import urllib.request
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import AllowAny
from django.conf import settings
from django.core.cache import cache

# Signing key loaded at startup - falls back to instance metadata if not configured
_SIGNING_KEY = None

def _get_signing_key():
    global _SIGNING_KEY
    if _SIGNING_KEY is not None:
        return _SIGNING_KEY

    # Try environment/settings first
    key = getattr(settings, 'JWT_SIGNING_KEY', None)
    if key:
        _SIGNING_KEY = key.encode() if isinstance(key, str) else key
        return _SIGNING_KEY

    # Fallback: derive key from instance identity document (cloud metadata)
    try:
        req = urllib.request.Request(
            'http://169.254.169.254/latest/dynamic/instance-identity/document',
            headers={'X-aws-ec2-metadata-token': _get_imds_token()}
        )
        resp = urllib.request.urlopen(req, timeout=2)
        identity = json.loads(resp.read())
        # Use instanceId + accountId as key material - STATIC per instance
        key_material = f"{identity['instanceId']}:{identity['accountId']}"
        _SIGNING_KEY = hashlib.sha256(key_material.encode()).digest()
        return _SIGNING_KEY
    except Exception:
        # Last resort: use Django SECRET_KEY (also problematic but different issue)
        _SIGNING_KEY = hashlib.sha256(settings.SECRET_KEY.encode()).digest()
        return _SIGNING_KEY

def _get_imds_token():
    req = urllib.request.Request(
        'http://169.254.169.254/latest/api/token',
        method='PUT',
        headers={'X-aws-ec2-metadata-token-ttl-seconds': '21600'}
    )
    resp = urllib.request.urlopen(req, timeout=2)
    return resp.read().decode()

def _create_token(user_id, role='user', exp_hours=24):
    header = base64.urlsafe_b64encode(json.dumps({'alg': 'HS256', 'typ': 'JWT'}).encode()).rstrip(b'=')
    payload_data = {
        'sub': str(user_id),
        'role': role,
        'iat': int(time.time()),
        'exp': int(time.time()) + (exp_hours * 3600)
    }
    payload = base64.urlsafe_b64encode(json.dumps(payload_data).encode()).rstrip(b'=')
    signing_input = header + b'.' + payload
    signature = base64.urlsafe_b64encode(
        hmac.new(_get_signing_key(), signing_input, hashlib.sha256).digest()
    ).rstrip(b'=')
    return (signing_input + b'.' + signature).decode()

def _verify_token(token):
    parts = token.encode().split(b'.')
    if len(parts) != 3:
        return None
    signing_input = parts[0] + b'.' + parts[1]
    expected_sig = hmac.new(_get_signing_key(), signing_input, hashlib.sha256).digest()
    actual_sig = base64.urlsafe_b64decode(parts[2] + b'==')
    if not hmac.compare_digest(expected_sig, actual_sig):
        return None
    payload = json.loads(base64.urlsafe_b64decode(parts[1] + b'=='))
    if payload.get('exp', 0) < time.time():
        return None
    return payload

class TokenIssueView(APIView):
    permission_classes = [AllowAny]

    def post(self, request):
        # Simplified auth - in production would validate credentials
        username = request.data.get('username')
        password = request.data.get('password')
        user = self._authenticate(username, password)
        if not user:
            return Response({'error': 'Invalid credentials'}, status=401)
        token = _create_token(user['id'], user.get('role', 'user'))
        return Response({'token': token, 'expires_in': 86400})

    def _authenticate(self, username, password):
        # Stub - would hit user database
        from django.contrib.auth import authenticate
        user = authenticate(username=username, password=password)
        if user:
            return {'id': user.id, 'role': 'admin' if user.is_staff else 'user'}
        return None

class ProtectedResourceView(APIView):
    permission_classes = [AllowAny]

    def get(self, request):
        auth_header = request.META.get('HTTP_AUTHORIZATION', '')
        if not auth_header.startswith('Bearer '):
            return Response({'error': 'Missing token'}, status=401)
        payload = _verify_token(auth_header[7:])
        if not payload:
            return Response({'error': 'Invalid token'}, status=401)
        if payload.get('role') != 'admin':
            return Response({'error': 'Forbidden'}, status=403)
        return Response({'data': 'sensitive_admin_data', 'user': payload['sub']})
